export const BODY: string = "\n<p>ضبط السطوع يستغرق بضع دقائق فقط. ترفع الصورة وتسحب منزلقًا وتراجع النتيجة وتنزّل النسخة الأوضح.</p>\n<p>هذا البرنامج التعليمي يمر بالعملية كاملة خطوة بخطوة. يغطي المنزلق والإعدادات السريعة وأوضاع المقارنة وضبط التصدير التي تبقي النتيجة بمظهر طبيعي.</p>\n<p>في النهاية ستستطيع إصلاح صورة شخصية داكنة أو مشهد باهت أو لقطة شاشة ضبابية على أي جهاز. واحتفظ بالصورة الأصلية حتى تراجع النتيجة.</p>\n<h2 id=\"before-you-start\">قبل أن تبدأ: احكم على مدى ظلامها</h2>\n<p>انظر إلى الصورة قبل فتح الأداة. هل هي داكنة قليلًا أم داكنة جدًا أم داكنة في منطقة واحدة فقط؟ الجواب يخبرك كم تفتيح تحتاجه.</p>\n<p>صورة داكنة قليلًا تحتاج 10 إلى 15 بالمئة. صورة داكنة جدًا قد تحتاج 30 بالمئة أو أكثر، لكن الحركات الكبيرة تخاطر بغسل الأضواء. وراجع إن كانت الصورة مسطحة أو باهتة أيضًا: صورة داكنة ومسطحة تحتاج سطوعًا وتباينًا معًا، فخطط للتعديلين لا لواحد فقط.</p>\n<p>افتح <a href=\"/ar/taadil-sutoo-as-sura/\">محرر سطوع الصورة</a> في متصفحك. كل شيء يعمل محليًا، فصورتك لا تُرفع أبدًا إلى خادم.</p>\n<h2 id=\"step-by-step\">اضبط السطوع في خمس خطوات</h2>\n<p>العملية نفسها لصورة أو لقطة شاشة أو مستند ممسوح ضوئيًا. ارفع الصورة واضبط وقارن وصدّر وتحقق من التنزيل.</p>\n<p>خذ وقتك مع المنزلق. الحركات الصغيرة تصنع فرقًا كبيرًا، والمعاينة تُظهر لك بالضبط متى تبدو الصورة جيدة. وافتح الملف المنزّل مرة قبل استخدامه، وتأكد من أن الصورة تبدو مضاءة بطبيعية وأن لا منطقة فاتحة أصبحت بيضاء.</p>\n<ol>\n<li>ارفع صورتك بسحبها إلى منطقة الرفع أو اختيارها من جهازك أو لصق لقطة شاشة بـCtrl+V.</li>\n<li>اسحب منزلق مستوى السطوع إلى اليمين للتفتيح أو إلى اليسار للتعتيم، مراقبًا المعاينة الحية.</li>\n<li>جرّب إعدادًا سريعًا لاختبار بنقرة واحدة، ثم دقّق بالمنزلق إن كانت النتيجة قريبة لكنها ليست جيدة تمامًا.</li>\n<li>استخدم أوضاع بعد وقبل والمقارنة المقسومة أو المقارنة بملء الشاشة لمراجعة النتيجة مقابل الأصل.</li>\n<li>اختر صيغة التصدير والجودة، ثم اضغط تنزيل لحفظ الصورة المعدلة.</li>\n</ol>\n<h2 id=\"using-the-slider\">كيف تستخدم منزلق السطوع</h2>\n<p>يتراوح المنزلق من قيم سالبة إلى موجبة، مع الصفر كلا تغيير. تحريكه إلى اليمين يفتّح الصورة، وتحريكه إلى اليسار يعتّمها.</p>\n<p>اسحب ببطء وراقب المعاينة. التحديث الحي يُظهر بالضبط كيف تستجيب الصورة، فتستطيع التوقف عند النقطة التي تبدو فيها الصورة جيدة. والحركات الصغيرة أفضل من الكبيرة: تغيير 10 إلى 15 بالمئة غالبًا يكفي، والحركات الأكبر تغسل الأضواء بسرعة.</p>\n<p>تُظهر الأداة صورتك بـ+15 بالمئة فور رفعها. نقطة البداية هذه تعطيك فكرة فورية عن مظهر تفتيح معتدل.</p>\n<h2 id=\"using-quick-presets\">كيف تستخدم الإعدادات السريعة</h2>\n<p>تضم الأداة إعدادات سريعة تطبق قيم سطوع شائعة بنقرة واحدة. إنها طريقة سريعة لتجربة مستويات مختلفة دون سحب المنزلق.</p>\n<p>اضغط إعدادًا سريعًا وراقب المعاينة. إذا كانت النتيجة قريبة لكنها ليست جيدة تمامًا، دقّق بالمنزلق من تلك النقطة. واستخدم الإعدادات السريعة لمقارنة الخيارات بسرعة: إعداد +15 بالمئة بجانب إعداد +30 بالمئة يُظهر كم تفتيح تتحمل الصورة.</p>\n<p>ولدفعة صور متشابهة، نفس الإعداد السريع يبقي النتائج متسقة. مجموعة لقطات داخلية داكنة، كلها مفتّحة بنفس القدر، تبدو كسلسلة.</p>\n<h2 id=\"using-compare-modes\">كيف تستخدم أوضاع المقارنة</h2>\n<p>أوضاع المقارنة تُظهر الأصل والنسخة المعدلة معًا. عرض بعد يُظهر الصورة المفتّحة، وعرض قبل يُظهر الأصل.</p>\n<p>المقارنة المقسومة هي الأكثر فائدة للعمل على السطوع. تُظهر النسختين جنبًا إلى جنب مع خط واضح بينهما، لتستطيع رؤية ما تغير بالضبط. والمقارنة بملء الشاشة تعطي أكبر عرض: إنها أفضل طريقة للحكم على صورة مفتّحة، لأن الصورة بالحجم الكامل تُظهر تفاصيل تخفيها معاينة صغيرة.</p>\n<p>راجع عرض المقارنة قبل كل تنزيل. نظرة سريعة تكتشف السطوع الزائد الذي قد تخفيه معاينة صغيرة.</p>\n<h2 id=\"brightening-a-dark-photo\">كيف تفتّح صورة داكنة</h2>\n<p>ارفع الصورة الداكنة واسحب المنزلق إلى +15 بالمئة. راجع المعاينة: يجب أن يُرى الموضوع بوضوح، وأن تحتفظ المناطق الفاتحة بالتفاصيل.</p>\n<p>إذا بقيت الصورة داكنة جدًا، زد المنزلق بخطوات صغيرة 5 بالمئة. كل خطوة تضيف قليلًا من الضوء، والمعاينة تُظهر متى تتوقف. وراقب الأضواء وأنت تتقدم: الجبهة والسماء وأي سطح أبيض ستحترق أولًا، وصورة ببقع بيضاء تبدو أسوأ من صورة داكنة.</p>\n<p>إذا بدت الصورة مسطحة بعد التفتيح، أضف تباينًا. افتح <a href=\"/ar/taadil-tabayun-as-sura/\">محرر تباين الصور</a> وطبّق دفعة صغيرة لاستعادة العمق.</p>\n<h2 id=\"darkening-a-bright-photo\">كيف تعتّم صورة فاتحة</h2>\n<p>اسحب المنزلق إلى اليسار لصورة فاتحة جدًا. قيم سالبة مثل -15 أو -30 بالمئة تعمّق الظلال وتستعيد الغنى.</p>\n<p>راجع الظلال وأنت تعتّم: يجب أن تكتسب عمقًا دون أن تصبح بقعًا سوداء صلبة بلا أي تفاصيل. والتعتيم يساعد أيضًا عندما تذهب صورة خلف نص: صورة معتّمة تجعل النص الأبيض مقروءًا، ما يناسب الشرائح والملصقات والرسوم الاجتماعية.</p>\n<p>ولصورة فاتحة جدًا في السماء وداكنة جدًا في المقدمة، اقبل حلًا وسطًا: السطوع يحرك كل شيء معًا، فلا اتجاه وحده سيصلح المنطقتين.</p>\n<h2 id=\"fixing-a-screenshot\">كيف تصلح لقطة شاشة داكنة</h2>\n<p>الصق لقطة شاشة مباشرة بـCtrl+V لتتخطى خطوة الحفظ. تظهر الصورة في المحرر فورًا، جاهزة للتفتيح.</p>\n<p>زد السطوع حتى يكون النص واضحًا والخلفية بيضاء. مستند بخلفية بيضاء نظيفة ونص داكن سهل القراءة والطباعة. وراقب الضجيج في المناطق الداكنة: لقطة مفتّحة كثيرًا قد تُظهر أنماط كتل خفيفة، خصوصًا في JPEG مضغوط مسبقًا.</p>\n<p>صدّر اللقطات كـPNG. الصيغة دون فقدان تبقي النص الصغير حادًا، وهو أمر مهم عندما تُظهر اللقطة ضبطًا أو رسالة خطأ.</p>\n<h2 id=\"previewing\">المعاينة قبل التنزيل</h2>\n<p>راجع المعاينة دائمًا قبل التنزيل. تحقق من أن الصورة تبدو مضاءة بطبيعية، وأن لا منطقة فاتحة أصبحت بيضاء، وأن الموضوع يُرى بوضوح.</p>\n<p>استخدم عرض المقارنة المقسومة لمراجعة التغيير: يُظهر الأصل والنسخة المعدلة جنبًا إلى جنب، لتستطيع رؤية ما فعله السطوع بالضبط. وقرّب على المناطق الفاتحة بالحجم الكامل: سماء أو جبهة تبدو جيدة في معاينة صغيرة قد تكون محترقة عند رؤيتها كبيرة.</p>\n<p>إذا بدت النتيجة مغسولة، اخفض المنزلق 5 بالمئة وراجع مجددًا. التخفيضات الصغيرة غالبًا تستعيد التفاصيل دون إعادة تعتيم الصورة.</p>\n<h2 id=\"choosing-export-format\">كيف تختار صيغة التصدير</h2>\n<p>اختر JPG للصور التي تنوي مشاركتها. يبقي الملفات صغيرة ويعمل في كل مكان، وضبط جودة عالية يبقي الصورة المفتّحة نظيفة.</p>\n<p>اختر PNG للقطات الشاشة والرسوم ذات النص. لا يفقد PNG شيئًا، فتبقى حواف الحروف حادة، ويحافظ على الشفافية عندما تحتاجها. واختر WebP عندما تريد ملفات صغيرة بجودة جيدة: يعمل جيدًا لصور الويب، مع أن بعض الأنظمة القديمة ما زالت ترفض الصيغة.</p>\n<p>تذكر أن ضبط الجودة يُخفى لـPNG، لأن PNG دون فقدان وليس له ضبط جودة لتغييره. هذا سلوك طبيعي، لا مشكلة في الأداة.</p>\n<h2 id=\"adjusting-on-mobile\">كيف تضبط السطوع على الهاتف أو الجهاز اللوحي</h2>\n<p>تعمل الأداة على شاشات اللمس، فتستطيع إصلاح صورة داكنة على الهاتف نفسه الذي التقطها. ارفع الصورة من معرضك واسحب المنزلق بإصبعك ونزّل النتيجة.</p>\n<p>سحب منزلق بالإصبع أقل دقة من الفأرة: استخدم الإعدادات السريعة لقيم دقيقة، ثم دقّق بسحبات صغيرة. وراجع المعاينة بالحجم الكامل قبل التنزيل: تغيير سطوع يبدو جيدًا على شاشة هاتف صغيرة قد يكون قويًا جدًا عند رؤيته على حاسوب.</p>\n<p>تُحفظ الملفات المنزّلة في مجلد التنزيلات المعتاد لديك. ومن هناك يمكنك مشاركة الصورة المفتّحة مباشرة إلى تطبيق محادثة أو بريد أو منشور اجتماعي.</p>\n<h2 id=\"troubleshooting\">كيف تحل مشاكل السطوع الشائعة</h2>\n<p>إذا بدت الصورة مغسولة، فالمنزلق مرتفع جدًا. اخفضه بخطوات صغيرة حتى تُظهر الأضواء التفاصيل مجددًا، ثم راجع الظلال.</p>\n<p>وإذا بقيت الصورة داكنة بعد التفتيح، فقد يكون الأصل داكنًا جدًا لإنقاذه: صورة شبه سوداء لا يمكن إصلاحها بالسطوع وحده، وإعادة التقاطها هي الخيار الأفضل. وإذا ظهر ضجيج في الظلال، فالتفتيح قوي جدًا للمصدر: اخفض المنزلق واقبل صورة أدكن قليلًا، أو ابدأ من أصل أفضل.</p>\n<p>وإذا بدت المعاينة مختلفة عن التنزيل، راجع صيغة التصدير والجودة: ضبط جودة JPG منخفض قد ينعّم الصورة كلها، بما فيها المناطق الفاتحة.</p>\n<h2 id=\"brightness-plus-contrast\">سطوع مع تباين: الثنائي الشائع</h2>\n<p>صورة داكنة ومسطحة تحتاج سطوعًا وتباينًا معًا. فتّح أولًا لرفع المستوى العام، ثم أضف تباينًا لاستعادة العمق.</p>\n<p>استخدم <a href=\"/ar/taadil-tabayun-as-sura/\">محرر تباين الصور</a> بعد التفتيح، عندما تبدو الصورة رمادية وبلا حياة: دفعة تباين صغيرة تعيد الظلال والأضواء. واعمل الخطوات بالترتيب: سطوع أولًا ثم تباين. عكسهما قد يجعل الحكم على ضبط التباين أصعب، لأن الصورة ما زالت داكنة.</p>\n<p>راجع عرض المقارنة بعد كل خطوة: العرض المقسوم يُظهر بالضبط ما فعله كل ضبط، فتستطيع التوقف عندما تبدو الصورة جيدة.</p>\n<h2 id=\"saving-settings\">كيف تحفظ ضبطك للمرة القادمة</h2>\n<p>دوّن قيمة السطوع التي نجحت لمجموعة صور متشابهة. ملاحظة قصيرة، مثل لقطات داخلية +20 بالمئة، توفر عليك التخمين في المرة القادمة.</p>\n<p>ولدفعة صور التُقطت بنفس الضوء، استخدم نفس القيمة لكلها: سطوع متسق عبر مجموعة يبدو احترافيًا، بينما القيم المختلطة تبدو عشوائية. واحتفظ بالملفات الأصلية: قيمة سطوع تناسب صورة قد لا تناسب أخرى، والأصل يتيح لك تجربة مستوى مختلف دون ضرر إضافي.</p>\n<p>راجع ملاحظاتك من حين لآخر. مع تحسن كاميرتك وإضاءتك، ستتغير قيم السطوع التي تحتاجها، وقد تضللك الملاحظات القديمة.</p>\n<h2 id=\"quick-tips\">نصائح سريعة لسطوع أفضل</h2>\n<p>فتّح بخطوات صغيرة. تغيير 5 بالمئة في كل مرة يمنحك تحكمًا، بينما قفزة كبيرة قد تتجاوز القيمة الصحيحة قبل أن تلاحظ.</p>\n<p>راجع الأضواء، لا الظلال فقط: صورة مفرطة التفتيح عندما تفقد المناطق الفاتحة التفاصيل، حتى لو بدت المناطق الداكنة جيدة. واستخدم عرض المقارنة دائمًا: نظرة سريعة إلى الأصل بجانب التعديل تكتشف أخطاء تخفيها معاينة صغيرة.</p>\n<p>احفظ الصورة الأصلية دون تعديل. بمجرد أن يُدمج تغيير سطوع في تصدير، لا يمكن التراجع عنه من ذلك الملف.</p>\n<h2 id=\"brightening-for-presentation\">كيف تفتّح صورة لعرض تقديمي</h2>\n<p>صورة تُستخدم في شريحة يجب أن تكون فاتحة بما يكفي لتُرى من آخر القاعة. صورة داكنة على شاشة كبيرة تبدو ضبابية، بينما صورة مضاءة جيدًا تُقرأ بوضوح.</p>\n<p>فتّح صور الشرائح قليلًا أكثر مما تفعل لخلاصة: أجهزة العرض تغسل الألوان وتقلل السطوع، فصورة تبدو جيدة على حاسوب محمول قد تبدو داكنة عند العرض. وراجع الصورة على جهاز العرض الحقيقي إن استطعت: شريحة اختبار تُظهر إن كان السطوع يصمد في القاعة، حيث الضوء مختلف جدًا عن مكتبك.</p>\n<p>أبقِ التفتيح متساويًا عبر الشريحة كلها: صورة فاتحة في زاوية وداكنة في أخرى تشتت الجمهور عن الكلمات فوقها.</p>\n<h2 id=\"brightening-old-scans\">كيف تفتّح صورًا قديمة ممسوحة ضوئيًا</h2>\n<p>الصور القديمة الممسوحة ضوئيًا غالبًا داكنة وباهتة. العمر يخفت الطباعة، والماسح يقرأ النغمات خطأ، والنتيجة صورة رمادية ضبابية تحتاج دفعة.</p>\n<p>زد السطوع بخطوات صغيرة وراقب الوجوه. الهدف صورة تبدو كما بدت الطباعة الأصلية عندما كانت جديدة، لا نسخة مغسولة منها. والمسحات القديمة غالبًا تحتاج تباينًا إضافة إلى السطوع: الطباعة الباهتة لها نطاق نغمي ضئيل، فدفعة سطوع مع زيادة تباين صغيرة تستعيد العمق.</p>\n<p>اعمل من أفضل مسح لديك: مسح عالي الدقة يفتّح أفضل بكثير من مسح منخفض الدقة، لأن هناك تفاصيل أكثر ليكشفها التعديل.</p>\n<p>للمقارنة، اقرأ <a href=\"/ar/blog/sutoo-vs-taarid-vs-tabayun/\">سطوع أم تعريض أم تباين: أساسيات التعديل</a>. وللدليل الكامل، راجع <a href=\"/ar/blog/dalil-muharrir-sutoo-as-suwar/\">دليل محرر سطوع الصور الكامل</a>، ولإصلاح التباين المسطح من التفتيح استخدم <a href=\"/ar/taadil-tabayun-as-sura/\">محرر تباين الصور</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كيف أفتّح صورة على هاتفي؟","answer":"افتح محرر سطوع الصورة في متصفح هاتفك وارفع الصورة من معرضك واسحب المنزلق إلى اليمين بإصبعك. واستخدم إعدادًا سريعًا لقيمة دقيقة، وراجع عرض المقارنة ونزّل النتيجة."},{"question":"أي قيمة سطوع يجب أن أستخدم لصورة داخلية داكنة؟","answer":"ابدأ عند +15 بالمئة، وهي قيمة المعاينة في الأداة، وزد بخطوات 5 بالمئة حتى يُرى الموضوع بوضوح. معظم الصور الداخلية تحتاج 15 إلى 30 بالمئة، مع مراقبة الأضواء فلا تحترق."},{"question":"هل يمكنني تعتيم صورة فاتحة جدًا؟","answer":"نعم، اسحب المنزلق إلى اليسار نحو قيم سالبة، مثل -15 أو -30 بالمئة. التعتيم يعمّق الظلال ويستعيد الغنى في صورة مفرطة التعريض. وراجع الظلال فلا تصبح بقعًا سوداء صلبة."},{"question":"لماذا تُظهر صورتي المفتّحة ضجيجًا محببًا؟","answer":"التفتيح يكشف الضجيج الذي كان مخفيًا في الظلال، وضغط JPEG يزيده سوءًا. اخفض المنزلق واقبل صورة أدكن قليلًا، أو ابدأ من أصل أفضل التُقط بضوء جيد. ودفعة لطيفة تُبقي الضجيج منخفضًا."},{"question":"هل أضبط السطوع قبل التباين أم بعده؟","answer":"السطوع أولًا ثم التباين. التفتيح يرفع المستوى العام، والتباين يستعيد العمق الذي قد يغسله التفتيح. عملها بهذا الترتيب يجعل كل ضبط أسهل حكمًا في عرض المقارنة."},{"question":"هل يمكنني التراجع عن تغيير سطوع بعد التنزيل؟","answer":"لا من الملف المنزّل، إذ يُدمج التغيير في التصدير. احتفظ بالصورة الأصلية لتستطيع تجربة مستوى سطوع آخر. وفي الأداة، استخدم خيار إعادة الضبط للعودة إلى الصفر قبل التنزيل."}];
